type MemberEntity = LoginData['entity'];

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === 'string' && value.trim().length > 0;

const parseStoredLoginData = (
  value: string | null,
): Partial<LoginData> | null => {
  if (!value || value === 'undefined') {
    return null;
  }

  try {
    const parsed: unknown = JSON.parse(value);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      ? parsed as Partial<LoginData>
      : null;
  } catch {
    return null;
  }
};

const overlayDefinedFields = <T extends object>(
  base: T,
  overlay: Partial<T> | null | undefined,
): T => {
  if (!overlay) {
    return base;
  }

  const next: T = {...base};

  (Object.keys(overlay) as Array<keyof T>).forEach(key => {
    const value = overlay[key];

    if (value !== undefined) {
      next[key] = value as T[keyof T];
    }
  });

  return next;
};

const mergeMemberEntity = (
  storedLoginData: Partial<LoginData> | null,
  currentLoginData: LoginData | null,
  refreshedLoginData: Partial<LoginData>,
  userId: string,
): MemberEntity | null => {
  const matchedEntities = [
    currentLoginData?.entity,
    storedLoginData?.entity,
    refreshedLoginData.entity,
  ].filter(
    (candidate): candidate is MemberEntity =>
      isNonEmptyString(candidate?.id) && candidate.id === userId,
  );

  if (matchedEntities.length === 0) {
    return null;
  }

  return matchedEntities.reduce(
    (merged, candidate) => overlayDefinedFields(merged, candidate),
  );
};

const mergeRefreshedLoginData = (
  storedLoginData: Partial<LoginData> | null,
  currentLoginData: LoginData | null,
  refreshedLoginData: Partial<LoginData>,
  payload: RefreshTokenPayload,
): LoginData | null => {
  const entity = mergeMemberEntity(
    storedLoginData,
    currentLoginData,
    refreshedLoginData,
    payload.userId,
  );
  const accessToken = refreshedLoginData.accessToken;
  const refreshToken =
    refreshedLoginData.refreshToken ??
    storedLoginData?.refreshToken ??
    currentLoginData?.refreshToken ??
    payload.refreshToken;

  if (
    !entity ||
    !isNonEmptyString(accessToken) ||
    !isNonEmptyString(refreshToken)
  ) {
    return null;
  }

  const dependents =
    refreshedLoginData.dependents ??
    storedLoginData?.dependents ??
    currentLoginData?.dependents;

  return {
    ...currentLoginData,
    ...storedLoginData,
    ...refreshedLoginData,
    accessToken,
    entity,
    refreshToken,
    ...(dependents !== undefined ? {dependents} : {}),
  };
};

test('refreshToken keeps cached identity when the response entity is a stub', async () => {
  const storedSession = {
    accessToken: 'old-access-token',
    refreshToken: 'old-refresh-token',
    entity: {
      id: 'member-id',
      name: 'Member Name',
      contacts: [{id: null, key: 'mobile', value: '12345678'}],
    },
    dependents: [{id: 'dependent-id'}],
  };
  mockGetGlobalAppState.mockReturnValue({
    loginData: storedSession,
    user: null,
    setLoginData: mockSetLoginData,
  });
  mockAsyncStorageGetItem.mockResolvedValue(JSON.stringify(storedSession));
  mockPostRequest.mockResolvedValue({
    data: {
      success: true,
      data: {
        accessToken: 'new-access-token',
        entity: {
          id: 'member-id',
        },
      },
    },
  });

  await refreshToken({
    refreshToken: 'old-refresh-token',
