export const refreshToken = async (
  payload: RefreshTokenPayload,
): Promise<RefreshTokenResponse> => {
  try {
    const response = await postRequest<RefreshTokenResponse>(
      urls.API_REFRESH_TOKEN,
      payload,
    );
    const refreshResponse = response.data;

    if (refreshResponse?.success && refreshResponse.data?.accessToken) {
      const globalAppState = getGlobalAppState();
      const storedLoginData = parseStoredLoginData(
        await AsyncStorage.getItem('memberData'),
      );
      const mergedLoginData = mergeRefreshedLoginData(
        storedLoginData,
        globalAppState?.loginData ?? null,
        refreshResponse.data,
        payload,
      );

      if (!mergedLoginData) {
        throw new Error('Refreshed session is missing member identity');
      }

      await Promise.all([
        AsyncStorage.setItem(
          'memberData',
          JSON.stringify(mergedLoginData),
        ),
        Keychain.setGenericPassword(
          'password',
          mergedLoginData.accessToken,
        ),
      ]);
      globalAppState?.setLoginData(mergedLoginData);
    }

    return refreshResponse;
  } catch (error) {
    throw error;
  }
};

