import axios, {InternalAxiosRequestConfig, AxiosResponse, AxiosError, AxiosRequestConfig} from 'axios';
import urls from '@api/urls';
import {getGlobalAppState} from '@store/AppContext';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { removeAllExcept } from '@helper/async-storage-utils';
import {jwtDecode} from "jwt-decode";
import Config from 'react-native-config';
import * as Keychain from 'react-native-keychain';

const apiClient = axios.create({
  baseURL: urls.API_BASE_URL,
  timeout: 100000,
  headers: {
    'Content-Type': 'application/json',
  },
});

enum HttpStatus {
  BadRequest = 400,
  Unauthorized = 401,
  Forbidden = 403,
  NotFound = 404,
  InternalServerError = 500,
}

interface StoredMemberData {
  entity?: {
    id?: string;
  };
  refreshToken?: string;
}

interface RefreshTokenResponse {
  data?: {
    accessToken?: string;
  };
  success?: boolean;
}

interface RefreshTokenPayload {
  refreshToken: string;
  userId: string;
}

interface RetryableRequestConfig extends InternalAxiosRequestConfig {
  _retry?: boolean;
}

let logoutPromise: Promise<void> | null = null;
let refreshPromise: Promise<RefreshTokenResponse> | null = null;

const refreshAccessToken = (
  payload: RefreshTokenPayload,
): Promise<RefreshTokenResponse> => {
  if (!refreshPromise) {
    refreshPromise = $api.refreshToken(payload).finally(() => {
      refreshPromise = null;
    });
  }

  return refreshPromise;
};

const normalizeRequestUrl = (url: string): string =>
  url.split(/[?#]/, 1)[0].replace(/\/+$/, '');

const isRefreshTokenRequest = (requestUrl?: string): boolean => {
  if (!requestUrl) {
    return false;
  }

  const normalizedRequestUrl = normalizeRequestUrl(requestUrl);
  const normalizedRefreshUrl = normalizeRequestUrl(urls.API_REFRESH_TOKEN);

  return (
    normalizedRequestUrl === normalizedRefreshUrl ||
    normalizedRequestUrl.endsWith(
      '/v1/health-passport/auth/refreshToken',
    )
  );
};

apiClient.interceptors.request.use(
  async (config: InternalAxiosRequestConfig) => {
    const globalAppState = getGlobalAppState();
    let memberData = await AsyncStorage.getItem('memberData');
    memberData = JSON.parse(memberData);

    if (memberData?.accessToken) {
      const decoded = jwtDecode(memberData?.accessToken);
      config.headers['Authorization'] = `Bearer ${memberData?.accessToken}`;
      config.headers['username'] = decoded.username;
    }
    config.headers['Accept-Language'] = globalAppState.AcceptLanguage();

    if (config.headers['x-client-secret'] && config.headers['x-client-id']) {
      return config;
    }

    config.headers['x-client-secret'] = Config.CLIENT_SECRET;
    config.headers['x-client-id'] = 'health-passport';
    // console.log(`[config-request] `, config)
    return config;
  },
  (error: AxiosError) => {
    return Promise.reject(error);
  }
);

// Response interceptor.
apiClient.interceptors.response.use(
  async (response: AxiosResponse) => {
    return response.data;
  },
  async (error: AxiosError) => {
    if (error.response) {
      switch (error.response.status) {
        case HttpStatus.BadRequest:
          console.error('api-client.ts Bad request parameters.');
          break;
        case HttpStatus.Unauthorized:
          // break;
          console.error('api-client.ts Unauthorized, may require re-login.');
          const memberDataValue = await AsyncStorage.getItem('memberData');
          let memberData: StoredMemberData | null = null;

          try {
            memberData = memberDataValue
              ? JSON.parse(memberDataValue) as StoredMemberData
              : null;
          } catch {
            memberData = null;
          }

          const userId = memberData?.entity?.id;
          const refreshToken = memberData?.refreshToken;
          const originalRequest = error.config as
            | RetryableRequestConfig
            | undefined;

          if (
            isRefreshTokenRequest(originalRequest?.url) ||
            !originalRequest ||
            originalRequest._retry ||
            !userId ||
            !refreshToken
          ) {
            await handleLogout();
            return Promise.reject(error);
          }

          originalRequest._retry = true;

          const payload = {
            userId,
            refreshToken,
          };
          try {
            const response = await refreshAccessToken(payload);

            if (response?.success && response?.data?.accessToken) {
              // Re-try the previous request
              return apiClient(originalRequest);
            }
          } catch {
            // The expired session is cleared below.
          }

          await handleLogout();
          return Promise.reject(error);
        case HttpStatus.Forbidden:
          console.error('api-client.ts Access forbidden.');
          break;
        case HttpStatus.NotFound:
          console.error('api-client.ts Resource not found.');
          break;
        case HttpStatus.InternalServerError:
          console.error('api-client.ts Internal server error.');
          break;
        default:
          console.error(`apiClient.ts Unknown error: ${error.response.status}`);
      }
    } else if (error.request) {
      console.error('api-client.ts No response received, please check your network connection.');
    } else {
      console.error('api-client.ts Request setting error:', error.message);
    }
    return Promise.reject(error);
  }
);

export const getRequest = async <T>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  try {
    const response = await apiClient.get<T>(url, config)
    return {
      data: response,
    }
  } catch (error) {
    handleRequestError(error);
    if (axios.isAxiosError(error) && error.response) {
      throw error.response.data as AxiosResponse<T>;
    } else {
      throw error as AxiosError;
    }
  }
};

export const postRequest = async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  try {
    const response = await apiClient.post<T>(url, data, config);
    return {
      data: response,
    }
  } catch (error) {
    handleRequestError(error);
    if (axios.isAxiosError(error) && error.response) {
      throw error.response.data as AxiosResponse<T>;
    } else {
      throw error as AxiosError;
    }
  }
};

export const putRequest = async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  try {
    const response = await apiClient.put<T>(url, data, config);
    return {
      data: response,
    }
  } catch (error) {
    handleRequestError(error);
    if (axios.isAxiosError(error) && error.response) {
      throw error.response.data as AxiosResponse<T>;
    } else {
      throw error as AxiosError;
    }
  }
};

export const deleteRequest = async <T>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  try {
    const response = await apiClient.delete<T>(url, config);
    return {
      data: response,
    }
  } catch (error) {
    handleRequestError(error);
    if (axios.isAxiosError(error) && error.response) {
      throw error.response.data as AxiosResponse<T>;
    } else {
      throw error as AxiosError;
    }
  }
};

export const handleRequestError = (error: unknown): unknown => {
  if (axios.isAxiosError(error)) {
    if (error.response) {
      console.error(
        `api-client.ts Request failed with status ${error.response.status}.`,
      );
      return error.response.data;
    }

    console.error('api-client.ts Request failed without a server response.');
    return error;
  } else {
    console.error('api-client.ts Unknown error:', error);
    return error;
  }
};

const performLogout = async (): Promise<void> => {
  try {
    // await AsyncStorage.clear();
    await Promise.all([
      Keychain.resetGenericPassword(),
      removeAllExcept('cachePhoneNumber'),
    ]);
    const globalAppState = getGlobalAppState();
    globalAppState?.setLoginData(null);
    globalAppState?.setPlan(null);

    if ($NavigationActions.getNavigationName()?.name === $routeNames.login) {
      return;
    }

    $NavigationActions.reset(
      [{
        'name': $routeNames.login
      }], 0
    );
  } catch (e) {
    console.log(`Exception encountered @ handleLogout ${JSON.stringify(e)}`);
  }
};

export const handleLogout = async (): Promise<void> => {
  if (logoutPromise) {
    return logoutPromise;
  }

  logoutPromise = performLogout();

  try {
    await logoutPromise;
  } finally {
    logoutPromise = null;
  }
};

const mockGetRequest = jest.fn();
const mockPostRequest = jest.fn();
const mockGetGlobalAppState = jest.fn();
const mockAsyncStorageGetItem = jest.fn();
const mockAsyncStorageSetItem = jest.fn();
const mockSetGenericPassword = jest.fn();
const mockSetLoginData = jest.fn();

jest.mock('../src/api/api-client.ts', () => ({
  deleteRequest: jest.fn(),
  getRequest: (...args: unknown[]) => mockGetRequest(...args),
  postRequest: (...args: unknown[]) => mockPostRequest(...args),
  putRequest: jest.fn(),
}));

jest.mock('@react-native-async-storage/async-storage', () => ({
  __esModule: true,
  default: {
    getItem: (key: string): Promise<string | null> =>
      mockAsyncStorageGetItem(key),
    setItem: (key: string, value: string): Promise<void> =>
      mockAsyncStorageSetItem(key, value),
  },
}));

jest.mock('@store/AppContext', () => ({
  getGlobalAppState: () => mockGetGlobalAppState(),
}));

jest.mock('react-native-keychain', () => ({
  setGenericPassword: (username: string, password: string): Promise<boolean> =>
    mockSetGenericPassword(username, password),
}));

jest.mock('react-native-config', () => ({
  BASE_URL: 'https://api.example.test',
  BASE_URL_1: 'https://api.example.test',
}));

jest.mock('../src/config/index', () => ({
  __esModule: true,
  default: {},
}));

import {getUser, refreshToken} from '../src/api/api';

describe('member authentication session', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockGetGlobalAppState.mockReturnValue({
      loginData: null,
      user: null,
      setLoginData: mockSetLoginData,
      setCommonModalKey: jest.fn(),
      setShowErrorModal: jest.fn(),
      setErrorModalText: jest.fn(),
    });
    mockAsyncStorageGetItem.mockResolvedValue(null);
    mockAsyncStorageSetItem.mockResolvedValue(undefined);
    mockSetGenericPassword.mockResolvedValue(true);
  });

  test('getUser skips the request when cached member identity is missing', async () => {
    mockAsyncStorageGetItem.mockResolvedValue(
      JSON.stringify({
        accessToken: 'access-token',
        refreshToken: 'refresh-token',
      }),
    );

    await expect(getUser()).resolves.toBeUndefined();

    expect(mockGetRequest).not.toHaveBeenCalled();
  });

  test('getUser falls back to the in-memory user when memberData is malformed', async () => {
    mockGetGlobalAppState.mockReturnValue({
      loginData: null,
      user: {id: 'in-memory-user-id'},
      setLoginData: mockSetLoginData,
    });
    mockAsyncStorageGetItem.mockResolvedValue('{invalid-json');
    mockGetRequest.mockResolvedValue({
      data: {data: {id: 'in-memory-user-id'}},
    });

    await expect(getUser()).resolves.toEqual({id: 'in-memory-user-id'});

    expect(mockGetRequest).toHaveBeenCalledWith(
      'https://api.example.test/v1/health-passport/user/in-memory-user-id',
      {},
    );
  });

  test('refreshToken merges token-only responses into the existing identity', async () => {
    const storedSession = {
      accessToken: 'old-access-token',
      refreshToken: 'old-refresh-token',
      entity: {
        id: 'member-id',
        name: 'Member Name',
      },
      dependents: [{id: 'dependent-id'}],
      expires_in: '300',
    };
    mockGetGlobalAppState.mockReturnValue({
      loginData: storedSession,
      user: null,
      setLoginData: mockSetLoginData,
    });
    mockAsyncStorageGetItem.mockResolvedValue(JSON.stringify(storedSession));
    mockPostRequest.mockResolvedValue({
      data: {
        success: true,
        data: {
          accessToken: 'new-access-token',
        },
      },
    });

    await expect(
      refreshToken({
        refreshToken: 'old-refresh-token',
        userId: 'member-id',
      }),
    ).resolves.toEqual({
      success: true,
      data: {
        accessToken: 'new-access-token',
      },
    });

    const expectedSession = {
      ...storedSession,
      accessToken: 'new-access-token',
    };
    expect(mockSetLoginData).toHaveBeenCalledWith(expectedSession);
    expect(mockAsyncStorageSetItem).toHaveBeenCalledWith(
      'memberData',
      JSON.stringify(expectedSession),
    );
    expect(mockSetGenericPassword).toHaveBeenCalledWith(
      'password',
      'new-access-token',
    );
  });

  test('refreshToken keeps cached identity when the response entity is a stub', async () => {
    const storedSession = {
      accessToken: 'old-access-token',
      refreshToken: 'old-refresh-token',
      entity: {
        id: 'member-id',
        name: 'Member Name',
        contacts: [{id: null, key: 'mobile', value: '12345678'}],
      },
      dependents: [{id: 'dependent-id'}],
    };
    mockGetGlobalAppState.mockReturnValue({
      loginData: storedSession,
      user: null,
      setLoginData: mockSetLoginData,
    });
    mockAsyncStorageGetItem.mockResolvedValue(JSON.stringify(storedSession));
    mockPostRequest.mockResolvedValue({
      data: {
        success: true,
        data: {
          accessToken: 'new-access-token',
          entity: {
            id: 'member-id',
          },
        },
      },
    });

    await refreshToken({
      refreshToken: 'old-refresh-token',
      userId: 'member-id',
    });

    expect(mockSetLoginData).toHaveBeenCalledWith({
      ...storedSession,
      accessToken: 'new-access-token',
      entity: storedSession.entity,
    });
  });

  test('refreshToken ignores a refreshed entity that belongs to a different member', async () => {
    const storedSession = {
      accessToken: 'old-access-token',
      refreshToken: 'old-refresh-token',
      entity: {
        id: 'member-id',
        name: 'Member Name',
      },
      dependents: [],
    };
    mockGetGlobalAppState.mockReturnValue({
      loginData: storedSession,
      user: null,
      setLoginData: mockSetLoginData,
    });
    mockAsyncStorageGetItem.mockResolvedValue(JSON.stringify(storedSession));
    mockPostRequest.mockResolvedValue({
      data: {
        success: true,
        data: {
          accessToken: 'new-access-token',
          entity: {
            id: 'other-member-id',
            name: 'Other Member',
          },
        },
      },
    });

    await refreshToken({
      refreshToken: 'old-refresh-token',
