interface LaunchMemberSession {
  accessToken?: string;
  entityId?: string;
  refreshToken?: string;
}

export interface LaunchSessionDecision {
  hasLocation: boolean;
  hasMemberData: boolean;
  shouldLogout: boolean;
  shouldRefresh: boolean;
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === 'string' && value.trim().length > 0;

export const parseStoredMemberSession = (
  value: string | null,
): LaunchMemberSession | null => {
  if (!value || value === 'undefined') {
    return null;
  }

  try {
    const parsed: unknown = JSON.parse(value);

    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return null;
    }

    const session = parsed as {
      accessToken?: unknown;
      entity?: {id?: unknown};
      refreshToken?: unknown;
    };

    return {
      accessToken: isNonEmptyString(session.accessToken)
        ? session.accessToken
        : undefined,
      entityId: isNonEmptyString(session.entity?.id)
        ? session.entity.id
        : undefined,
      refreshToken: isNonEmptyString(session.refreshToken)
        ? session.refreshToken
        : undefined,
    };
  } catch {
    return null;
  }
};

export const isJwtExpired = (
  accessToken: string | undefined,
  nowMs: number = Date.now(),
): boolean => {
  if (!isNonEmptyString(accessToken)) {
    return true;
  }

  try {
    const payloadPart = accessToken.split('.')[1];

    if (!payloadPart) {
      return true;
    }

    const paddedPayload = payloadPart.replace(/-/g, '+').replace(/_/g, '/');
    const normalizedPayload = paddedPayload.padEnd(
      paddedPayload.length + ((4 - (paddedPayload.length % 4)) % 4),
      '=',
    );
    const decodedPayload: unknown = JSON.parse(atob(normalizedPayload));

    if (
      !decodedPayload ||
      typeof decodedPayload !== 'object' ||
      Array.isArray(decodedPayload)
    ) {
      return true;
    }

    const exp = (decodedPayload as {exp?: unknown}).exp;

    if (typeof exp !== 'number') {
      return false;
    }

    return exp * 1000 <= nowMs;
  } catch {
    return true;
  }
};

export const decideLaunchSession = (
  session: LaunchMemberSession | null,
  nowMs: number = Date.now(),
): LaunchSessionDecision => {
  if (!session) {
    return {
      hasLocation: false,
      hasMemberData: false,
      shouldLogout: false,
      shouldRefresh: false,
    };
  }

  if (!session.entityId || !session.refreshToken) {
    return {
      hasLocation: true,
      hasMemberData: false,
      shouldLogout: true,
      shouldRefresh: false,
    };
  }

  if (isJwtExpired(session.accessToken, nowMs)) {
    return {
      hasLocation: true,
      hasMemberData: true,
      shouldLogout: false,
      shouldRefresh: true,
    };
  }

  return {
    hasLocation: true,
    hasMemberData: true,
    shouldLogout: false,
    shouldRefresh: false,
  };
};

