import {
  decideLaunchSession,
  isJwtExpired,
  parseStoredMemberSession,
} from '../src/helper/launch-session';

const createJwt = (exp?: number): string => {
  const header = Buffer.from(JSON.stringify({alg: 'none', typ: 'JWT'})).toString(
    'base64url',
  );
  const payload = Buffer.from(
    JSON.stringify(exp === undefined ? {sub: 'member-id'} : {exp}),
  ).toString('base64url');

  return `${header}.${payload}.signature`;
};

describe('launch session restore', () => {
  test('treats a missing cache as a first-time user', () => {
    expect(parseStoredMemberSession(null)).toBeNull();
    expect(decideLaunchSession(null)).toEqual({
      hasLocation: false,
      hasMemberData: false,
      shouldLogout: false,
      shouldRefresh: false,
    });
  });

  test('logs out a leftover token-only session from 1.2.1', () => {
    const session = parseStoredMemberSession(
      JSON.stringify({
        accessToken: 'access-token',
        refreshToken: 'refresh-token',
      }),
    );

    expect(session).toEqual({
      accessToken: 'access-token',
      entityId: undefined,
      refreshToken: 'refresh-token',
    });
    expect(decideLaunchSession(session)).toEqual({
      hasLocation: true,
      hasMemberData: false,
      shouldLogout: true,
      shouldRefresh: false,
    });
  });

  test('refreshes when the access token is expired but identity remains', () => {
    const expiredAccessToken = createJwt(1);
    const session = parseStoredMemberSession(
      JSON.stringify({
        accessToken: expiredAccessToken,
        refreshToken: 'refresh-token',
        entity: {id: 'member-id'},
      }),
    );

    expect(isJwtExpired(expiredAccessToken, 2_000)).toBe(true);
    expect(decideLaunchSession(session, 2_000)).toEqual({
      hasLocation: true,
      hasMemberData: true,
      shouldLogout: false,
      shouldRefresh: true,
    });
  });

  test('keeps a complete unexpired session on the main tabs', () => {
    const liveAccessToken = createJwt(4_000_000_000);
    const session = parseStoredMemberSession(
      JSON.stringify({
        accessToken: liveAccessToken,
        refreshToken: 'refresh-token',
        entity: {id: 'member-id'},
      }),
    );

    expect(decideLaunchSession(session, 1_000)).toEqual({
      hasLocation: true,
      hasMemberData: true,
      shouldLogout: false,
      shouldRefresh: false,
    });
  });
});

