const ts = require('typescript');
const path = require('path');
const fs = require('fs');

const cwd = process.cwd();
const configPath = path.join(cwd, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
if (configFile.error) {
  console.error('readConfigFile', ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
  process.exit(1);
}

const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, cwd);
parsed.options.moduleResolution = ts.ModuleResolutionKind.Node10 ?? ts.ModuleResolutionKind.NodeJs;
parsed.options.noEmit = true;

const extraFiles = [
  path.join(cwd, 'App.tsx'),
  path.join(cwd, '__tests__/launch-session.test.ts'),
];
const rootNames = Array.from(new Set([...parsed.fileNames, ...extraFiles]));
const program = ts.createProgram({ rootNames, options: parsed.options });

const changed = new Set([
  path.normalize(path.join(cwd, 'App.tsx')),
  path.normalize(path.join(cwd, 'src/helper/launch-session.ts')),
  path.normalize(path.join(cwd, 'src/store/AppContext.tsx')),
  path.normalize(path.join(cwd, '__tests__/launch-session.test.ts')),
]);

const configDiags = ts.getPreEmitDiagnostics(program).filter(d => !d.file);
if (configDiags.length) {
  console.log('=== CONFIG DIAGNOSTICS ===');
  for (const d of configDiags) {
    console.log(ts.flattenDiagnosticMessageText(d.messageText, '\n'), 'code', d.code);
  }
}

function printDiags(label, diags, sf) {
  const related = diags.filter(d => !d.file || path.normalize(d.file.fileName) === path.normalize(sf.fileName));
  if (!related.length) {
    console.log(`${label}: none`);
    return;
  }
  for (const d of related) {
    const pos = d.file && d.start != null ? d.file.getLineAndCharacterOfPosition(d.start) : null;
    const loc = pos ? `${pos.line + 1}:${pos.character + 1}` : '';
    console.log(`${label} TS${d.code} ${loc} ${ts.flattenDiagnosticMessageText(d.messageText, '\n')}`);
  }
}

console.log('fileNames include changed:', [...changed].map(f => ({
  f: path.relative(cwd, f),
  inProgram: !!program.getSourceFile(f) || !!program.getSourceFiles().find(sf => path.normalize(sf.fileName) === f),
})));

for (const sf of program.getSourceFiles()) {
  const n = path.normalize(sf.fileName);
  if (!changed.has(n)) continue;
  console.log('\n====', path.relative(cwd, n), '====');
  printDiags('syntactic', program.getSyntacticDiagnostics(sf), sf);
  printDiags('semantic', program.getSemanticDiagnostics(sf), sf);
  printDiags('suggestion', program.getSuggestionDiagnostics(sf), sf);
}
EOF

